# Example root for one POC. The poc-deploy skill writes this file into the
# new app repo as infra/main.tf, with the module vendored at
# infra/modules/poc-app. Each POC has its own state: prefix apps/<app_id> in
# the shared state bucket, set at init:
#
#   terraform init -backend-config="bucket=<project>-tfstate" -backend-config="prefix=apps/<app_id>"
#   terraform apply -var-file=app.tfvars
terraform {
  required_version = ">= 1.5"
  required_providers {
    google      = { source = "hashicorp/google", version = "~> 6.0" }
    google-beta = { source = "hashicorp/google-beta", version = "~> 6.0" }
    random      = { source = "hashicorp/random", version = "~> 3.6" }
  }
  backend "gcs" {}
}

provider "google" {
  project               = var.project_id
  region                = var.region
  user_project_override = true
  billing_project       = var.project_id
}

provider "google-beta" {
  project               = var.project_id
  region                = var.region
  user_project_override = true
  billing_project       = var.project_id
}

variable "app_id" { type = string }
variable "display_name" { type = string }
variable "project_id" { type = string }
variable "region" {
  type    = string
  default = "australia-southeast1"
}
variable "dns_zone_name" { type = string }
variable "notification_channel" { type = string }
variable "firebase_api_key" { type = string }
variable "firebase_app_id" { type = string }
variable "github_repository_id" { type = string }
variable "github_owner_id" { type = string }
variable "client_access" {
  type    = bool
  default = false
}
variable "scheduled_jobs" {
  type    = list(object({ name = string, schedule = string, path = string }))
  default = []
}

module "app" {
  source               = "./modules/poc-app"
  app_id               = var.app_id
  display_name         = var.display_name
  project_id           = var.project_id
  region               = var.region
  dns_zone_name        = var.dns_zone_name
