#!/usr/bin/env bun
/**
 * Rebuild every user's poc_<id> claims from users/<email>, the source of
 * truth. Repairs a claims_sync_failed audit entry. Dry run unless --apply.
 *
 *   FIREBASE_PROJECT_ID=<project> bun run resync [--apply]
 *
 * Claims that are not poc_* are left alone. A poc_* claim with no matching
 * allocation is removed and the user's refresh tokens are revoked.
 */
import { withAppClaim, type AppRole } from "@lsv-poc/poc-auth";
import { adminApp, appDb } from "@lsv-poc/poc-auth/firebase";
import { getAuth } from "firebase-admin/auth";

const apply = process.argv.includes("--apply");
const auth = getAuth(adminApp());
const users = await appDb("platform").collection("users").get();
for (const doc of users.docs) {
  const email = doc.id;
  const want = (doc.data().pocs ?? {}) as Record<string, AppRole>;
  const user = await auth.getUserByEmail(email).catch(() => null);
  if (!user) {
    if (Object.keys(want).length) console.log(`${email}: allocated but no sign-in account yet (created on next grant)`);
    continue;
  }
  const have = user.customClaims ?? {};
  let next: Record<string, unknown> = Object.fromEntries(Object.entries(have).filter(([k]) => !k.startsWith("poc_")));
  for (const [id, role] of Object.entries(want)) next = withAppClaim(next, id, role);
  const removed = Object.keys(have).filter((k) => k.startsWith("poc_") && !(k in next));
  if (JSON.stringify(have) === JSON.stringify(next)) continue;

