export function createHubHandlers(d: HubDeps) {
  const now = d.now ?? (() => Math.floor(Date.now() / 1000));
  const pocDomain = d.pocDomain ?? "poc.nicholaswood.com.au";

  /** The signed-in hub user, re-read from users/<email> on every request. */
  async function caller(request: Request): Promise<{ user: UserRecord } | Response> {
    const s = verifySession(readCookie(request.headers.get("cookie")), d.secret(), now());
    if (!s || s.app !== "hub") return json(401, { error: "Sign in" });
    const user = await d.store.getUser(s.email);
    if (!user) return json(403, { error: "No access" });
    return { user };
  }

  async function platformAdmin(request: Request, mutating: boolean): Promise<{ user: UserRecord } | Response> {
    if (mutating && request.headers.get("origin") !== new URL(d.origin).origin) return json(403, { error: "Forbidden" });
    const c = await caller(request);
    if (c instanceof Response) return c;
    if (!c.user.platformAdmin) {
      d.log.warn("admin route refused", { event: "hub.admin_refused", email: c.user.email });
      return json(403, { error: "Platform admins only" });
    }
    return c;
  }

  async function parseAllocation(request: Request, needRole: boolean) {
    const b = (await request.json().catch(() => null)) as { email?: unknown; pocId?: unknown; role?: unknown } | null;
    const email = typeof b?.email === "string" ? b.email.toLowerCase().trim() : "";
    const pocId = b?.pocId;
    const role = needRole ? parseRole(b?.role) : null;
    if (!EMAIL.test(email) || !isValidAppId(pocId) || (needRole && !role)) return null;
    return { email, pocId, role };
  }
