/**
 * Policy for the Next.js sign-in pages (and the hub\x27s own pages). Next emits
 * inline bootstrap scripts without a nonce on prerendered pages, so inline is
 * allowed; what this buys is that nothing loads from, posts to or is framed by
 * another origin, and the only outside calls are Firebase sign-in. The
 * packaged POC page has its own stricter, hash-based policy (buildCsp).
 * next.config cannot import workspace TypeScript, so each next.config carries
 * this string inline and a test keeps them identical.
 */
export const SIGN_IN_CSP =
  ${JSON.stringify(CSP)};
`; await Bun.write(f,s);
for (const [file, sources] of [["apps/hub/next.config.ts",["/:path*"]],["template/host/next.config.ts",["/sign-in","/auth/:path*"]]]) {
  let t=await Bun.file(file).text();
  const block = sources.map(src=>`      // Sign-in pages: see SIGN_IN_CSP in poc-auth (kept identical by a test). Production only; dev needs eval.\n      ...(process.env.NODE_ENV === "production" ? [{ source: ${JSON.stringify(src)}, headers: [{ key: "Content-Security-Policy", value: SIGN_IN_CSP }] }] : []),\n`).join("");
  t=t.replace("const nextConfig: NextConfig = {", `const SIGN_IN_CSP =\n  ${JSON.stringify(CSP)};\n\nconst nextConfig: NextConfig = {`);
  t=t.replace("    return [\n", "    return [\n"+block);
  await Bun.write(file,t);
}
await Bun.write("packages/poc-auth/test/sign-in-csp.test.ts", `import { expect, test } from "bun:test";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { SIGN_IN_CSP, externalOriginsIn } from "../src";

const root = join(import.meta.dir, "../../..");

test("sign-in policy names only the Firebase sign-in hosts", () => {
  expect(externalOriginsIn(SIGN_IN_CSP).sort()).toEqual(["https://identitytoolkit.googleapis.com", "https://securetoken.googleapis.com"]);
  expect(SIGN_IN_CSP).toContain("frame-ancestors \x27none\x27");
  expect(SIGN_IN_CSP).toContain("object-src \x27none\x27");
});

test("hub and host template carry the same policy as the package", () => {
  for (const f of ["apps/hub/next.config.ts", "template/host/next.config.ts"]) {
    expect(readFileSync(join(root, f), "utf8")).toContain(JSON.stringify(SIGN_IN_CSP));
  }
